/*
 * The glossy silk ribbons behind the hero and CTA. The artwork is generated by
 * scripts/build-ribbons.mjs into public/ribbons; see that file for how.
 */

type RibbonProps = {
  shape?: "hero" | "cta";
  flip?: boolean;
  className?: string;
};

export function Ribbon({ shape = "hero", flip = false, className }: RibbonProps) {
  return (
    // eslint-disable-next-line @next/next/no-img-element -- decorative static SVG, no optimisation needed
    <img
      className={className}
      src={`/ribbons/${shape}.svg`}
      alt=""
      aria-hidden
      decoding="async"
      style={flip ? { transform: "scaleX(-1)" } : undefined}
    />
  );
}
